-- DRAFT, NOT APPLIED. Faroes 3D terrain rebuilt from the Faroese Environment Agency's 2015 surface model (DSM 2015,
-- 2 m, Umhvørvisstovan), every level (14 Nov 2026). Written by tools/sun3d/faroes/build_faroes_2015.py (branch claude/sun3d-faroes-2015).
-- Replaces ArcticDEM everywhere in the Faroes (it read ~3.3 m low against the agency's contours and had no Risin og Kellingin);
-- the 2015 file is within -0.4..+0.6 m of the agency's 2009 contours on gentle ground and has the sea stacks.
-- Cleaned first, whole islands: 2672 land holes (399,837 cells of 2 m) filled from the agency's 2009 contour lines
-- (never ArcticDEM), 2993 water holes inside the coastline (lagoons, harbour basins: 722,790 cells) laid flat
-- at their rim's level, 687 floating blunder pieces (14,190 cells) taken out and filled the same way; every
-- building footprint filled from the ground round it (the houses are drawn from terrain_house_tiles, never twice).
--
-- Before applying: upload the 248 files of upload.txt (106.6 MB) to the public bucket `terrain` (new names: phones
-- keep files by id + byte size, so nothing old is overwritten). Old files can stay in the bucket.
--
-- 1. terrain_regions 'faroes' (the wide grid, same box and size): the 2015 ground, block means, summits and stacks at their tops.
update public.terrain_regions set path = 'faroes_dsm15_wide.png', bytes = 862938, base_m = 0, step_m = 0.5,
  note = 'Faroese Environment Agency DSM 2015 (2 m), bare ground (houses taken out), 2048 x 2048, isolated tops kept. Was ArcticDEM 32 m.',
  color_credit = 'Heights, ground photos, buildings and water: Faroese Environment Agency, Umhvørvisstovan (DSM 2015; Myndakort, Bygningar, Topo; November 2026). House heights measured in the 2015 surface model.'
  where id = 'faroes';

-- 2. terrain_range_regions: 33 sharp boxes at 2 m (2048 x 2048 cells, 4,096 m), every rated shot's subject at least
--    1 km inside one (pickRange), the stand pin too wherever the two fit one box. Bare ground. Feed the sun times.
on conflict (id) do update set north = excluded.north, south = excluded.south, west = excluded.west, east = excluded.east, n = excluded.n, width_m = excluded.width_m,
  depth_m = excluded.depth_m, base_m = excluded.base_m, step_m = excluded.step_m, cell_m = excluded.cell_m, path = excluded.path, bytes = excluded.bytes, note = excluded.note;

-- 3. terrain_near_regions: the same fine boxes (their aerial photos stay), heights from the 2015 file at up to 2048 cells
--    (1.9 to 4.4 m); a new one for Klakkur (no fine box held its stand pin).
update public.terrain_near_regions set n = 2048, base_m = -5, step_m = 0.02, path = 'fo_vagar_west_dsm15.png', bytes = 2314025, note = 'Umhvørvisstovan DSM 2015, bare ground, 4.2 m cells.' where id = 'fo_vagar_west' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_vagar_south_dsm15.png', bytes = 1425437, note = 'Umhvørvisstovan DSM 2015, bare ground, 3.7 m cells.' where id = 'fo_vagar_south' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_sandavagur_dsm15.png', bytes = 2165742, note = 'Umhvørvisstovan DSM 2015, bare ground, 3.0 m cells.' where id = 'fo_sandavagur' and parent = 'faroes';
update public.terrain_near_regions set n = 1536, base_m = -2, step_m = 0.02, path = 'fo_kvivik_dsm15.png', bytes = 623976, note = 'Umhvørvisstovan DSM 2015, bare ground, 2.0 m cells.' where id = 'fo_kvivik' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_streymoy_north_dsm15.png', bytes = 2538021, note = 'Umhvørvisstovan DSM 2015, bare ground, 5.4 m cells.' where id = 'fo_streymoy_north' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_eysturoy_north_dsm15.png', bytes = 2119979, note = 'Umhvørvisstovan DSM 2015, bare ground, 3.8 m cells.' where id = 'fo_eysturoy_north' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_kalsoy_north_dsm15.png', bytes = 1033465, note = 'Umhvørvisstovan DSM 2015, bare ground, 2.8 m cells.' where id = 'fo_kalsoy_north' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_torshavn_south_dsm15.png', bytes = 2410886, note = 'Umhvørvisstovan DSM 2015, bare ground, 3.9 m cells.' where id = 'fo_torshavn_south' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_nordradalur_dsm15.png', bytes = 3234249, note = 'Umhvørvisstovan DSM 2015, bare ground, 3.8 m cells.' where id = 'fo_nordradalur' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_vidoy_dsm15.png', bytes = 1367382, note = 'Umhvørvisstovan DSM 2015, bare ground, 2.3 m cells.' where id = 'fo_vidoy' and parent = 'faroes';
update public.terrain_near_regions set n = 2048, base_m = -2, step_m = 0.02, path = 'fo_sandoy_dsm15.png', bytes = 1020507, note = 'Umhvørvisstovan DSM 2015, bare ground, 2.8 m cells.' where id = 'fo_sandoy' and parent = 'faroes';
  on conflict (id) do update set path = excluded.path, bytes = excluded.bytes, n = excluded.n, base_m = excluded.base_m, step_m = excluded.step_m, color_path = excluded.color_path, color_bytes = excluded.color_bytes;

-- 4. Close-up boxes: the 36 round 2 boxes (ArcticDEM ground, guessed house heights in buildings_path) go; 36 new 1,504 m boxes
--    at 1 m (the 2 m file upsampled, cubic, never above or below its four cells) in terrain_detail_regions_v4, bare ground
--    (bare = true: the houses come from terrain_house_tiles), class mask (0 ground, 3 sea / lake / lagoon, 4 stream) and
--    aerial photo as round 2. Each sits inside its shot's fine box with the stand pin at least 150 m in.
delete from public.terrain_detail_regions where parent = 'faroes';
on conflict (id) do update set north = excluded.north, south = excluded.south, west = excluded.west, east = excluded.east, n = excluded.n, width_m = excluded.width_m, depth_m = excluded.depth_m,
  base_m = excluded.base_m, step_m = excluded.step_m, cell_m = excluded.cell_m, path = excluded.path, bytes = excluded.bytes, mask_path = excluded.mask_path, mask_bytes = excluded.mask_bytes,
  color_path = excluded.color_path, color_bytes = excluded.color_bytes, bare = excluded.bare, note = excluded.note;

-- 5. terrain_house_tiles: every building outline of the agency (Bygningar) over the islands, with eave / ridge heights,
--    roof form and ridge direction MEASURED in the 2015 surface model (h: dsm; h: assumed where the 2015 file does not show
--    it: built since, or too small for 2 m cells), roof / wall colours from the aerial photos where a box has one (rc / wc).
--    Drawn within 8 km of the stand pin, never in the sun times.
on conflict (id) do update set path = excluded.path, bytes = excluded.bytes, count = excluded.count, note = excluded.note;
